package lk.ac.sliit.ridelink.driver.infrastructure.persistence.adapter;
import lk.ac.sliit.ridelink.driver.domain.enums.VehicleType; import lk.ac.sliit.ridelink.driver.domain.model.Vehicle; import lk.ac.sliit.ridelink.driver.domain.repository.VehicleRepository; import lk.ac.sliit.ridelink.driver.infrastructure.persistence.mapper.VehiclePersistenceMapper; import lk.ac.sliit.ridelink.driver.infrastructure.persistence.repository.SpringDataVehicleRepository; import org.springframework.stereotype.Component; import java.util.*;
@Component public class VehiclePersistenceAdapter implements VehicleRepository { private final SpringDataVehicleRepository r; public VehiclePersistenceAdapter(SpringDataVehicleRepository r){this.r=r;} public Vehicle save(Vehicle v){return VehiclePersistenceMapper.domain(r.save(VehiclePersistenceMapper.entity(v)));} public Optional<Vehicle> findById(UUID id){return r.findById(id).map(VehiclePersistenceMapper::domain);} public List<Vehicle> findByDriverId(UUID id){return r.findByDriverIdOrderById(id).stream().map(VehiclePersistenceMapper::domain).toList();} public boolean existsByRegistrationNumber(String v){return r.existsByRegistrationNumberIgnoreCase(v);} public boolean existsActiveByDriverId(UUID id){return r.existsByDriverIdAndActiveTrue(id);} public Optional<Vehicle> findFirstActiveMatching(UUID id,VehicleType type){return r.findFirstByDriverIdAndActiveTrueAndVehicleTypeOrderById(id,type).map(VehiclePersistenceMapper::domain);} }
